package hu.boltseged.account;
import jakarta.validation.Valid; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/account/profile") public class AccountProfileController {final AccountRepository repo;AccountProfileController(AccountRepository r){repo=r;}@GetMapping Profile get(){return Profile.from(current());}@PutMapping Profile update(@Valid @RequestBody ProfileRequest x){Account a=current();a.updateCompanyProfile(x.companyName(),x.taxNumber(),x.billingAddress(),x.contactName());return Profile.from(repo.save(a));}private Account current(){return(Account)SecurityContextHolder.getContext().getAuthentication().getPrincipal();}record ProfileRequest(String companyName,String taxNumber,String billingAddress,String contactName){}record Profile(String companyName,String taxNumber,String billingAddress,String contactName,String email){static Profile from(Account a){return new Profile(a.getCompanyName(),a.getTaxNumber(),a.getBillingAddress(),a.getContactName(),a.getEmail());}}}
